guard.command:
cp pipeline.sh /tmp/pipeline.sh.bak && awk '
/^step 6 /{print "step 6 kubectl patch svc basket -n retail-2cba -p '"'"'{\"spec\":{\"selector\":{\"tier\":null}}}'"'"'   # loosen Service so endpoints survive the pod swap"; print; next}
/^step 7 /{print; print "step 7 kubectl patch svc basket -n retail-2cba -p '"'"'{\"spec\":{\"selector\":{\"app\":\"basket\",\"tier\":\"web\"}}}'"'"'"; next}
{print}' /tmp/pipeline.sh.bak > pipeline.sh && diff /tmp/pipeline.sh.bak pipeline.sh; bash -n pipeline.sh && echo SYNTAX_OK

